class IndependentSpyAndAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.spy = self.add_equity("SPY", Resolution.DAILY).symbol
        self.aapl = self.add_equity("AAPL", Resolution.DAILY).symbol
        self.ibm = self.add_equity("IBM", Resolution.DAILY).symbol
        self.bac = self.add_equity("BAC", Resolution.DAILY).symbol
        self.aig = self.add_equity("AIG", Resolution.DAILY).symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = RollingWindow[float](101)
        self.aapl_rsi = self.rsi(
            self.aapl, 14, MovingAverageType.WILDERS, Resolution.DAILY
        )

        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.pending_orders = {}

        self.set_warm_up(101, Resolution.DAILY)

    def on_data(self, data: Slice):
        if self.spy in data.bars:
            self.spy_closes.add(data.bars[self.spy].close)

        if self.aapl in data.bars:
            aapl_close = data.bars[self.aapl].close
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close

        if self.is_warming_up:
            return

        if any(symbol not in data.bars for symbol in self.symbols):
            return

        spy_close = data.bars[self.spy].close
        aapl_close = data.bars[self.aapl].close

        # Strategy A: sell before buy.
        if self.strategy_a_lot > 0 and "A" not in self.pending_orders:
            if self.spy_closes.is_ready:
                today_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
                yesterday_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
                yesterday_close = self.spy_closes[1]

                if yesterday_close >= yesterday_sma and spy_close < today_sma:
                    ticket = self.market_order(self.spy, -self.strategy_a_lot)
                    self.pending_orders["A"] = ticket.order_id

        if self.strategy_a_lot == 0 and "A" not in self.pending_orders:
            if self.spy_closes.is_ready:
                today_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
                yesterday_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
                yesterday_close = self.spy_closes[1]

                if yesterday_close <= yesterday_sma and spy_close > today_sma:
                    quantity = int(0.40 * self.portfolio.total_portfolio_value / spy_close)
                    if quantity > 0:
                        ticket = self.market_order(self.spy, quantity)
                        self.pending_orders["A"] = ticket.order_id

        # Strategy B: sell before buy.
        if self.strategy_b_lot > 0 and "B" not in self.pending_orders:
            if self.aapl_rsi.is_ready and self.aapl_rsi.current.value > 60:
                ticket = self.market_order(self.aapl, -self.strategy_b_lot)
                self.pending_orders["B"] = ticket.order_id

        if self.strategy_b_lot == 0 and "B" not in self.pending_orders:
            if (
                self.aapl_rsi.is_ready
                and self.previous_aapl_close is not None
                and self.aapl_red_streak >= 3
                and self.portfolio.cash >= 20_000
            ):
                quantity = int(20_000 / aapl_close)
                if quantity > 0:
                    ticket = self.market_order(self.aapl, quantity)
                    self.pending_orders["B"] = ticket.order_id

    def on_order_event(self, order_event: OrderEvent):
        for strategy, order_id in list(self.pending_orders.items()):
            if order_event.order_id != order_id:
                continue

            if order_event.fill_quantity != 0:
                if strategy == "A":
                    self.strategy_a_lot += order_event.fill_quantity
                else:
                    self.strategy_b_lot += order_event.fill_quantity

            if order_event.status in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID,
            ):
                del self.pending_orders[strategy]
            break

