class TwoSlotStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = RollingWindow[float](101)
        self.aapl_closes = RollingWindow[float](4)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.aapl_red_streak = 0
        self.a_lot_shares = 0
        self.b_lot_shares = 0

    def OnData(self, data: Slice):
        has_bar = {}
        for ticker, symbol in self.symbols.items():
            has_bar[ticker] = data.Bars.ContainsKey(symbol)

        if has_bar["SPY"]:
            self.spy_closes.Add(float(data.Bars[self.spy].Close))

        if has_bar["AAPL"]:
            current_aapl_close = float(data.Bars[self.aapl].Close)

            if self.aapl_closes.Count > 0:
                if current_aapl_close < self.aapl_closes[0]:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_closes.Add(current_aapl_close)

        if not all(has_bar.values()):
            return

        if (not self.spy_closes.IsReady or
                not self.aapl_closes.IsReady or
                not self.aapl_rsi.IsReady):
            return

        spy_close = float(data.Bars[self.spy].Close)
        aapl_close = float(data.Bars[self.aapl].Close)

        spy_sma_today = sum(self.spy_closes[i] for i in range(100)) / 100.0
        spy_sma_yesterday = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
        spy_close_yesterday = self.spy_closes[1]

        spy_crosses_above = (
            spy_close_yesterday <= spy_sma_yesterday and
            spy_close > spy_sma_today
        )
        spy_crosses_below = (
            spy_close_yesterday >= spy_sma_yesterday and
            spy_close < spy_sma_today
        )

        # Slot 1: Strategy A
        if self.a_lot_shares > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.a_lot_shares)
            self.a_lot_shares = 0

        if self.a_lot_shares == 0 and spy_crosses_above:
            quantity = int((float(self.Portfolio.TotalPortfolioValue) * 0.40) // spy_close)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.a_lot_shares = quantity

        # Slot 2: Strategy B
        if self.b_lot_shares > 0 and float(self.aapl_rsi.Current.Value) > 60:
            self.MarketOrder(self.aapl, -self.b_lot_shares)
            self.b_lot_shares = 0

        if self.b_lot_shares == 0 and self.aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20_000:
                quantity = int(20_000 // aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.b_lot_shares = quantity

