class TwoSlotDailyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = RollingWindow[float](101)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.strategy_a_pending = False
        self.strategy_b_pending = False
        self.order_owners = {}

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data: Slice):
        bars = data.Bars

        for symbol in self.symbols:
            if bars.ContainsKey(symbol):
                bar = bars[symbol]
                if symbol == self.spy:
                    self.spy_closes.Add(float(bar.Close))
                elif symbol == self.aapl:
                    close = float(bar.Close)
                    self.aapl_rsi.Update(self.Time, close)

                    if self.aapl_previous_close is not None and close < self.aapl_previous_close:
                        self.aapl_red_streak += 1
                    else:
                        self.aapl_red_streak = 0

                    self.aapl_previous_close = close

        if self.IsWarmingUp:
            return

        if any(not bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        if not self.spy_closes.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = float(bars[self.spy].Close)
        aapl_close = float(bars[self.aapl].Close)

        spy_sma_today = sum(self.spy_closes[i] for i in range(100)) / 100.0
        spy_sma_yesterday = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
        spy_close_yesterday = self.spy_closes[1]

        spy_crosses_above = (
            spy_close_yesterday <= spy_sma_yesterday and
            spy_close > spy_sma_today
        )
        spy_crosses_below = (
            spy_close_yesterday >= spy_sma_yesterday and
            spy_close < spy_sma_today
        )

        # Sells are evaluated before buys.
        if self.strategy_a_lot > 0 and not self.strategy_a_pending and spy_crosses_below:
            self._submit_order(self.spy, -self.strategy_a_lot, "A")

        if self.strategy_b_lot > 0 and not self.strategy_b_pending and self.aapl_rsi.Current.Value > 60:
            self._submit_order(self.aapl, -self.strategy_b_lot, "B")

        if self.strategy_a_lot == 0 and not self.strategy_a_pending and spy_crosses_above:
            shares = int((0.40 * self.Portfolio.TotalPortfolioValue) / spy_close)
            if shares > 0:
                self._submit_order(self.spy, shares, "A")

        if self.strategy_b_lot == 0 and not self.strategy_b_pending and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20_000:
                shares = int(20_000 / aapl_close)
                if shares > 0:
                    self._submit_order(self.aapl, shares, "B")

    def _submit_order(self, symbol, quantity, owner):
        ticket = self.MarketOrder(symbol, quantity)
        self.order_owners[ticket.OrderId] = owner

        if owner == "A":
            self.strategy_a_pending = True
        else:
            self.strategy_b_pending = True

    def OnOrderEvent(self, orderEvent):
        if orderEvent.OrderId not in self.order_owners:
            return

        owner = self.order_owners[orderEvent.OrderId]

        if orderEvent.FillQuantity != 0:
            if owner == "A":
                self.strategy_a_lot += orderEvent.FillQuantity
            else:
                self.strategy_b_lot += orderEvent.FillQuantity

        if orderEvent.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
            if owner == "A":
                self.strategy_a_pending = False
            else:
                self.strategy_b_pending = False

            del self.order_owners[orderEvent.OrderId]

