class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_ma = self.SMA(self.spy, 50, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.previous_spy_close = None
        self.previous_spy_ma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.strategy_a_pending = False
        self.strategy_b_pending = False

    def OnData(self, data: Slice):
        if any(symbol not in data.Bars for symbol in self.symbols):
            return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        if self.previous_aapl_close is not None:
            if aapl_bar.Close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        indicators_ready = (
            self.spy_ma.IsReady
            and self.aapl_rsi.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_ma is not None
            and self.previous_aapl_close is not None
        )

        if indicators_ready:
            spy_crosses_above = (
                self.previous_spy_close <= self.previous_spy_ma
                and spy_bar.Close > self.spy_ma.Current.Value
            )
            spy_crosses_below = (
                self.previous_spy_close >= self.previous_spy_ma
                and spy_bar.Close < self.spy_ma.Current.Value
            )

            # Sells before buys.
            if self.strategy_a_lot > 0 and not self.strategy_a_pending and spy_crosses_below:
                self.strategy_a_pending = True
                self.MarketOrder(self.spy, -self.strategy_a_lot, tag="strategy_a_sell")

            if self.strategy_b_lot > 0 and not self.strategy_b_pending and self.aapl_rsi.Current.Value > 60:
                self.strategy_b_pending = True
                self.MarketOrder(self.aapl, -self.strategy_b_lot, tag="strategy_b_sell")

            if self.strategy_a_lot == 0 and not self.strategy_a_pending and spy_crosses_above:
                quantity = floor((self.Portfolio.TotalPortfolioValue * 0.40) / spy_bar.Close)
                if quantity > 0:
                    self.strategy_a_pending = True
                    self.MarketOrder(self.spy, quantity, tag="strategy_a_buy")

            if (
                self.strategy_b_lot == 0
                and not self.strategy_b_pending
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20_000
            ):
                quantity = floor(20_000 / aapl_bar.Close)
                if quantity > 0:
                    self.strategy_b_pending = True
                    self.MarketOrder(self.aapl, quantity, tag="strategy_b_buy")

        self.previous_spy_close = spy_bar.Close
        self.previous_spy_ma = self.spy_ma.Current.Value
        self.previous_aapl_close = aapl_bar.Close

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in [OrderStatus.Filled, OrderStatus.PartiallyFilled]:
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        if order.Tag == "strategy_a_buy":
            self.strategy_a_lot += order_event.FillQuantity
            if order_event.Status == OrderStatus.Filled:
                self.strategy_a_pending = False

        elif order.Tag == "strategy_a_sell":
            self.strategy_a_lot += order_event.FillQuantity
            if self.strategy_a_lot <= 0:
                self.strategy_a_lot = 0
            if order_event.Status == OrderStatus.Filled:
                self.strategy_a_pending = False

        elif order.Tag == "strategy_b_buy":
            self.strategy_b_lot += order_event.FillQuantity
            if order_event.Status == OrderStatus.Filled:
                self.strategy_b_pending = False

        elif order.Tag == "strategy_b_sell":
            self.strategy_b_lot += order_event.FillQuantity
            if self.strategy_b_lot <= 0:
                self.strategy_b_lot = 0
            if order_event.Status == OrderStatus.Filled:
                self.strategy_b_pending = False

